import { createClient, type PostgrestError, type SupabaseClient } from '@supabase/supabase-js';

/**
 * ============================================================================
 * SUPABASE SETUP GUIDE & SQL SCHEMA
 * ============================================================================
 * 1. Create a free project at https://supabase.com
 * 2. Open the SQL Editor in your Supabase Dashboard and run this query:
 *
 *    create table students (
 *      id bigint generated by default as identity primary key,
 *      student_id text unique not null,
 *      full_name text not null,
 *      program text not null,
 *      year_level text not null,
 *      email text not null,
 *      created_at timestamp with time zone default timezone('utc'::text, now()) not null
 *    );
 *
 *    -- Disable RLS for easy lab testing:
 *    alter table students disable row level security;
 *
 *    -- Or, if you prefer keeping RLS enabled with public CRUD access:
 *    -- alter table students enable row level security;
 *    -- create policy "Allow public CRUD" on students for all using (true) with check (true);
 *
 * 3. Copy your Project URL and Anon Public Key from:
 *    Project Settings -> API
 * 4. Add them to your .env file as:
 *    VITE_SUPABASE_URL="https://your-project-id.supabase.co"
 *    VITE_SUPABASE_ANON_KEY="your-anon-public-key"
 *    OR paste them directly into the fallback constants below.
 * ============================================================================
 */

export const SETUP_SQL = `create table students (
  id bigint generated by default as identity primary key,
  student_id text unique not null,
  full_name text not null,
  program text not null,
  year_level text not null,
  email text not null,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- Disable RLS for easy lab testing (or add a permissive policy)
alter table students disable row level security;`;

// Optional direct fallback if you prefer not to use a .env file:
const FALLBACK_SUPABASE_URL = 'https://plyhrfcsvtdulswihmia.supabase.co';
const FALLBACK_SUPABASE_ANON_KEY = 'sb_publishable__7nWBLf2Zu179PLzXvmLng_eVe1OLek';

const rawUrl = (import.meta.env.VITE_SUPABASE_URL || FALLBACK_SUPABASE_URL || '').trim();
const rawAnonKey = (
  import.meta.env.VITE_SUPABASE_ANON_KEY ||
  FALLBACK_SUPABASE_ANON_KEY ||
  ''
).trim();

function isValidSupabaseUrl(url: string): boolean {
  if (!url) return false;
  if (url.includes('your-project-id') || url.includes('MY_SUPABASE')) return false;
  try {
    const parsed = new URL(url);
    return parsed.protocol === 'https:' || parsed.protocol === 'http:';
  } catch {
    return false;
  }
}

function isValidAnonKey(key: string): boolean {
  if (!key) return false;
  if (key.includes('your-supabase-anon') || key.includes('MY_SUPABASE')) return false;
  return key.length > 10;
}

export const isSupabaseConfigured = isValidSupabaseUrl(rawUrl) && isValidAnonKey(rawAnonKey);

export const supabase: SupabaseClient | null = isSupabaseConfigured
  ? createClient(rawUrl, rawAnonKey)
  : null;

export interface ParsedDbError {
  message: string;
  field?: 'student_id';
}

export function parseSupabaseError(
  error: PostgrestError | Error | unknown,
  studentId?: string
): ParsedDbError {
  if (!error) {
    return { message: 'An unexpected database error occurred.' };
  }

  const pgError = error as Partial<PostgrestError>;
  const code = pgError.code || '';
  const msg = (pgError.message || (error instanceof Error ? error.message : String(error))).toLowerCase();

  // PostgreSQL unique constraint violation (duplicate student_id)
  if (
    code === '23505' ||
    msg.includes('duplicate key') ||
    msg.includes('students_student_id_key') ||
    msg.includes('unique constraint')
  ) {
    return {
      field: 'student_id',
      message: studentId
        ? `Student ID "${studentId}" is already registered. Please enter a unique Student ID.`
        : 'That Student ID is already registered. Please enter a unique Student ID.',
    };
  }

  // Table does not exist
  if (code === '42P01' || (msg.includes('relation') && msg.includes('does not exist'))) {
    return {
      message:
        'The "students" table was not found in your Supabase database. Run the SQL setup script in your Supabase SQL Editor first.',
    };
  }

  // Row Level Security blocked operation
  if (code === '42501' || msg.includes('row-level security')) {
    return {
      message:
        'Permission denied by Supabase Row Level Security (RLS). Disable RLS on the "students" table or add a public CRUD policy.',
    };
  }

  // Network / fetch error
  if (msg.includes('failed to fetch') || msg.includes('networkerror')) {
    return {
      message:
        'Unable to reach Supabase. Check your internet connection and verify that VITE_SUPABASE_URL is correct.',
    };
  }

  return {
    message: pgError.message || 'Could not complete the database request. Please try again.',
  };
}
